when.set-body:
@{
                    var converted = context.Request.Body.As(preserveContent: true);
                    var order = (JObject)converted["canonicalOrder"];

                    var integerFields = new string[] { "lineNumber" };
                    var decimalFields = new string[] { "quantity", "unitPrice", "discountAmount", "discountPercent", "taxPercent" };
                    var booleanFields = new string[] { "discountAppliedBeforeTax", "pricesIncludeTax" };

                    var lineToken = ((JObject)order["lines"])["line"];
                    order["lines"] = lineToken is JArray ? lineToken : new JArray(lineToken);
                    // Re-read: assigning an already-parented token stores a copy, not the original.
                    var lines = (JArray)order["lines"];

                    var targets = new List { order };
                    foreach (var addressField in new string[] { "billTo", "shipTo" })
                    {
                        if (order[addressField] is JObject)
                        {
                            targets.Add((JObject)order[addressField]);
                        }
                    }
                    foreach (var line in lines)
                    {
                        targets.Add((JObject)line);
                    }

                    foreach (var target in targets)
                    {
                        foreach (var property in target.Properties().ToList())
                        {
                            if (property.Value.Type == JTokenType.Null)
                            {
                                property.Remove();
                                continue;
                            }
                            if (property.Value.Type != JTokenType.String)
                            {
                                continue;
                            }
                            var text = ((string)property.Value).Trim();
                            if (integerFields.Contains(property.Name))
                            {
                                property.Value = long.Parse(text, System.Globalization.CultureInfo.InvariantCulture);
                            }
                            else if (decimalFields.Contains(property.Name))
                            {
                                property.Value = decimal.Parse(text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture);
                            }
                            else if (booleanFields.Contains(property.Name))
                            {
                                property.Value = text == "true" || text == "1";
                            }
                        }
                    }

                    return order.ToString();
                }
